    def _load_pipeline(self):
        import diffusers

        base_model = self._resolve_base_model()

        try:
            pipeline = diffusers.DiffusionPipeline.from_pretrained(base_model)
        except OSError as e:
            raise MlflowException(
                f"Failed to load base model '{base_model}' for the diffusers adapter. "
                f"Error: {e}"
