        try:
            if weight_name:
                pipeline.load_lora_weights(self.adapter_path, weight_name=weight_name)
            else:
                pipeline.load_lora_weights(self.adapter_path)
        except Exception as e:
            _logger.warning(
                f"Failed to load adapter weights from '{self.adapter_path}'. "
                f"The base pipeline will be used without the adapter. Error: {e}"
            )

        return pipeline

    def _get_pipeline(self):
        if self._pipeline is None:
            self._pipeline = self._load_pipeline()
        return self._pipeline

    def get_raw_model(self):
        """Return the underlying diffusion pipeline."""
        return self._get_pipeline()

    def _extract_prompts(self, data) -> list:
        import pandas as pd

        if isinstance(data, str):
            prompts = [data]
        elif isinstance(data, list):
            prompts = list(data)
        elif isinstance(data, dict):
            if "prompt" not in data:
                raise MlflowException(
                    "The input dictionary must contain a 'prompt' key."
                )
            value = data["prompt"]
            if isinstance(value, str):
                prompts = [value]
            elif isinstance(value, list):
                prompts = list(value)
            else:
                raise MlflowException(
                    "The 'prompt' value must be a string or list of strings."
                )
        elif isinstance(data, pd.DataFrame):
            if "prompt" in data.columns:
                prompts = data["prompt"].tolist()
            elif len(data.columns) == 1:
                prompts = data.iloc[:, 0].tolist()
            else:
                raise MlflowException(
                    "The input DataFrame must contain a 'prompt' column."
                )
        else:
            raise MlflowException(
                f"Unsupported input type: {type(data)}. Supported types are string, "
                "list of strings, dict with a 'prompt' key, and pandas DataFrame."
            )

